def run(benchmark_data):
    import time, math, random

    dim = int(benchmark_data.get("dim", 10))
    which = str(benchmark_data.get("benchmark", benchmark_data.get("name", ""))).lower()
    if which not in ("double_well", "rosenbrock"):
        which = ""  # unknown label: run both, harness picks

    # Energies and exact gradients. Gradients are hand-derived so the
    # optimizer descends the true surface the harness re-scores against.
    def dw_e(x):
        return sum((xi * xi - 1.0) ** 2 for xi in x)

    def dw_g(x):
        return [4.0 * xi * (xi * xi - 1.0) for xi in x]

    def rb_e(x):
        return sum(100.0 * (x[i + 1] - x[i] * x[i]) ** 2 + (1.0 - x[i]) ** 2
                   for i in range(len(x) - 1))

    def rb_g(x):
        n = len(x)
        g = [0.0] * n
        for i in range(n - 1):
            t = x[i + 1] - x[i] * x[i]
            g[i] += -400.0 * x[i] * t - 2.0 * (1.0 - x[i])
            g[i + 1] += 200.0 * t
        return g

    def lbfgs(e_fn, g_fn, x0):
        # Quasi-Newton path: fastest route to machine-precision minima.
        try:
            import numpy as np
            from scipy.optimize import minimize
        except ImportError:
            return None
        res = minimize(lambda z: float(e_fn(list(z))),
                       np.asarray(x0, dtype=float),
                       jac=lambda z: np.asarray(g_fn(list(z)), dtype=float),
                       method="L-BFGS-B",
                       options={"maxiter": 20000, "maxfun": 100000,
                                "ftol": 1e-18, "gtol": 1e-14})
        return [float(v) for v in res.x]

    def adam(e_fn, g_fn, x0, steps, lr, budget_s):
        # Dependency-free fallback: Adam on the analytic gradient.
        x = list(x0)
        n = len(x)
        m = [0.0] * n
        v = [0.0] * n
        b1, b2, eps = 0.9, 0.999, 1e-8
        best, best_e = list(x), e_fn(x)
        t0 = time.perf_counter()
        for t in range(1, steps + 1):
            g = g_fn(x)
            c1 = 1.0 - b1 ** t
            c2 = 1.0 - b2 ** t
            for i in range(n):
                m[i] = b1 * m[i] + (1.0 - b1) * g[i]
                v[i] = b2 * v[i] + (1.0 - b2) * g[i] * g[i]
                x[i] -= lr * (m[i] / c1) / (math.sqrt(v[i] / c2) + eps)
            if t % 50 == 0:
                e = e_fn(x)
                if e < best_e:
                    best_e, best = e, list(x)
                if best_e < 1e-14 or time.perf_counter() - t0 > budget_s:
                    break
        e = e_fn(x)
        if e < best_e:
            best = list(x)
        return best

    def solve(e_fn, g_fn, x0, adam_steps, adam_lr):
        t0 = time.perf_counter()
        x = lbfgs(e_fn, g_fn, x0)
        if x is None or e_fn(x) > 1e-10:
            seed = x if x is not None else x0
            x2 = adam(e_fn, g_fn, seed, adam_steps, adam_lr, budget_s=20.0)
            if x is None or e_fn(x2) < e_fn(x):
                x = x2
        return x, time.perf_counter() - t0

    random.seed(1234)
    out = {}

    if which in ("", "double_well"):
        x0 = [random.uniform(-2.0, 2.0) for _ in range(dim)]
        xs, dt = solve(dw_e, dw_g, x0, adam_steps=20000, adam_lr=0.02)
        out["double_well"] = {"final_state": [float(c) for c in xs],
                              "wall_clock_seconds": dt}

    if dim >= 2 and which in ("", "rosenbrock"):
        x0 = [(-1.2 if i % 2 == 0 else 1.0) for i in range(dim)]  # classic start
        xs, dt = solve(rb_e, rb_g, x0, adam_steps=60000, adam_lr=0.002)
        out["rosenbrock"] = {"final_state": [float(c) for c in xs],
                             "wall_clock_seconds": dt}

    return out
